import{_ as o,o as t,c as a,ag as i}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"HTTP Hooks Integration for Claude Deck","description":"","frontmatter":{},"headers":[],"relativePath":"plans/2026-03-05-http-hooks-integration-design.md","filePath":"plans/2026-03-05-http-hooks-integration-design.md"}'),d={name:"plans/2026-03-05-http-hooks-integration-design.md"};function n(r,e,s,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="http-hooks-integration-for-claude-deck" tabindex="-1">HTTP Hooks Integration for Claude Deck <a class="header-anchor" href="#http-hooks-integration-for-claude-deck" aria-label="Permalink to &quot;HTTP Hooks Integration for Claude Deck&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Claude Code recently added HTTP Hooks (<code>type: &quot;http&quot;</code>) — a new hook type that sends POST requests to URLs when lifecycle events fire. Claude Deck currently supports 3 hook types (command, prompt, agent) but has no HTTP hook support. This plan integrates HTTP hooks into Claude Deck at two levels: (1) full UI support for creating/editing HTTP hooks, and (2) a built-in webhook receiver so Claude Deck itself can monitor Claude Code activity in real-time via an Activity Dashboard.</p><p>Additionally, Claude Code has added 5 new event types not yet in Claude Deck, and there&#39;s a validation bug to fix.</p><h2 id="design-full-http-hooks-integration" tabindex="-1">Design: Full HTTP Hooks Integration <a class="header-anchor" href="#design-full-http-hooks-integration" aria-label="Permalink to &quot;Design: Full HTTP Hooks Integration&quot;">​</a></h2><h3 id="part-1-http-hook-type-support-schema-ui" tabindex="-1">Part 1: HTTP Hook Type Support (Schema + UI) <a class="header-anchor" href="#part-1-http-hook-type-support-schema-ui" aria-label="Permalink to &quot;Part 1: HTTP Hook Type Support (Schema + UI)&quot;">​</a></h3><h4 id="_1-1-backend-schema-changes" tabindex="-1">1.1 Backend Schema Changes <a class="header-anchor" href="#_1-1-backend-schema-changes" aria-label="Permalink to &quot;1.1 Backend Schema Changes&quot;">​</a></h4><p><strong>File: <code>backend/app/models/schemas.py</code></strong></p><p>Add to <code>Hook</code>, <code>HookCreate</code>, <code>HookUpdate</code> models:</p><ul><li><code>url: Optional[str]</code> — HTTP endpoint URL</li><li><code>headers: Optional[Dict[str, str]]</code> — HTTP headers with env var interpolation</li><li><code>allowedEnvVars: Optional[List[str]]</code> — Whitelist for env var expansion in headers</li></ul><p>Add to <code>VALID_HOOK_EVENTS</code> (line ~549):</p><ul><li><code>TeammateIdle</code>, <code>TaskCompleted</code>, <code>InstructionsLoaded</code>, <code>ConfigChange</code>, <code>WorktreeCreate</code>, <code>WorktreeRemove</code></li></ul><h4 id="_1-2-backend-api-fix-http-validation" tabindex="-1">1.2 Backend API Fix + HTTP Validation <a class="header-anchor" href="#_1-2-backend-api-fix-http-validation" aria-label="Permalink to &quot;1.2 Backend API Fix + HTTP Validation&quot;">​</a></h4><p><strong>File: <code>backend/app/api/v1/hooks.py</code></strong></p><ul><li><strong>Bug fix (line 66)</strong>: Type validation currently only allows <code>&quot;command&quot;</code> or <code>&quot;prompt&quot;</code> — add <code>&quot;agent&quot;</code> and <code>&quot;http&quot;</code></li><li>Add validation for HTTP hooks: require <code>url</code>, reject <code>command</code>/<code>prompt</code> fields, validate URL format</li><li>Ensure <code>headers</code> is a valid dict and <code>allowedEnvVars</code> is a list of strings</li></ul><h4 id="_1-3-backend-service-changes" tabindex="-1">1.3 Backend Service Changes <a class="header-anchor" href="#_1-3-backend-service-changes" aria-label="Permalink to &quot;1.3 Backend Service Changes&quot;">​</a></h4><p><strong>File: <code>backend/app/services/hook_service.py</code></strong></p><ul><li><code>_parse_hook_from_data</code>: Read <code>url</code>, <code>headers</code>, <code>allowedEnvVars</code> fields from settings JSON</li><li><code>add_hook</code> / <code>update_hook</code>: Write these fields when type is &quot;http&quot;</li><li>Handle the <code>async</code> field correctly (currently only for command hooks; HTTP hooks don&#39;t support it)</li></ul><h4 id="_1-4-frontend-type-updates" tabindex="-1">1.4 Frontend Type Updates <a class="header-anchor" href="#_1-4-frontend-type-updates" aria-label="Permalink to &quot;1.4 Frontend Type Updates&quot;">​</a></h4><p><strong>File: <code>frontend/src/types/hooks.ts</code></strong></p><ul><li>Add <code>&quot;http&quot;</code> to the type union</li><li>Add <code>url?: string</code>, <code>headers?: Record&lt;string, string&gt;</code>, <code>allowedEnvVars?: string[]</code> to Hook interfaces</li><li>Add 5 new events to <code>HOOK_EVENTS</code> array with labels, descriptions, icons</li><li>Add HTTP hook templates to <code>HOOK_TEMPLATES</code> (e.g., &quot;Slack Webhook Notification&quot;, &quot;Custom API Endpoint&quot;, &quot;Claude Deck Activity Logger&quot;)</li><li>Add <code>HTTP_HEADER_EXAMPLES</code> constant with common patterns (Authorization Bearer, Content-Type, custom headers)</li></ul><h4 id="_1-5-frontend-component-changes" tabindex="-1">1.5 Frontend Component Changes <a class="header-anchor" href="#_1-5-frontend-component-changes" aria-label="Permalink to &quot;1.5 Frontend Component Changes&quot;">​</a></h4><p><strong>HookWizard.tsx</strong> (Step 3 — type selection):</p><ul><li>Add fourth type button: HTTP with <code>Globe</code> icon</li><li>HTTP-specific form fields: <ul><li>URL input with validation</li><li>Key-value editor for headers (reusable component)</li><li>Tag-style input for allowedEnvVars</li></ul></li><li>Template selection includes HTTP templates</li></ul><p><strong>HookEditor.tsx</strong>:</p><ul><li>Add HTTP type toggle button</li><li>Conditionally render: URL input, headers key-value editor, allowedEnvVars when type=&quot;http&quot;</li><li>Hide command/prompt/model fields when type=&quot;http&quot;</li></ul><p><strong>HookCard.tsx</strong>:</p><ul><li>Add <code>Globe</code> icon for HTTP type</li><li>Display URL (truncated) instead of command/prompt preview</li><li>Badge showing header count if &gt; 0</li></ul><p><strong>HookDetailDialog.tsx</strong>:</p><ul><li>HTTP section showing: full URL, headers table (values partially masked), allowedEnvVars list</li></ul><h4 id="_1-6-new-shared-component-keyvalueeditor" tabindex="-1">1.6 New Shared Component: KeyValueEditor <a class="header-anchor" href="#_1-6-new-shared-component-keyvalueeditor" aria-label="Permalink to &quot;1.6 New Shared Component: KeyValueEditor&quot;">​</a></h4><p><strong>File: <code>frontend/src/components/shared/KeyValueEditor.tsx</code></strong></p><p>Reusable key-value pair editor for HTTP headers:</p><ul><li>Add/remove rows</li><li>Key input + value input per row</li><li>Env var hint (show <code>$VAR_NAME</code> syntax help)</li><li>Used by HookWizard and HookEditor</li></ul><hr><h3 id="part-2-claude-deck-webhook-receiver-activity-dashboard" tabindex="-1">Part 2: Claude Deck Webhook Receiver + Activity Dashboard <a class="header-anchor" href="#part-2-claude-deck-webhook-receiver-activity-dashboard" aria-label="Permalink to &quot;Part 2: Claude Deck Webhook Receiver + Activity Dashboard&quot;">​</a></h3><h4 id="_2-1-database-model" tabindex="-1">2.1 Database Model <a class="header-anchor" href="#_2-1-database-model" aria-label="Permalink to &quot;2.1 Database Model&quot;">​</a></h4><p><strong>File: <code>backend/app/models/database.py</code></strong></p><p>New table <code>hook_events</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>id: Integer, primary key, autoincrement</span></span>
<span class="line"><span>event_type: String, not null (e.g., &quot;PreToolUse&quot;, &quot;PostToolUse&quot;)</span></span>
<span class="line"><span>session_id: String, nullable</span></span>
<span class="line"><span>tool_name: String, nullable</span></span>
<span class="line"><span>matcher: String, nullable</span></span>
<span class="line"><span>payload: JSON (full hook input payload)</span></span>
<span class="line"><span>received_at: DateTime, default=now</span></span></code></pre></div><h4 id="_2-2-webhook-receiver-api" tabindex="-1">2.2 Webhook Receiver API <a class="header-anchor" href="#_2-2-webhook-receiver-api" aria-label="Permalink to &quot;2.2 Webhook Receiver API&quot;">​</a></h4><p><strong>New file: <code>backend/app/api/v1/webhook_receiver.py</code></strong></p><p>Endpoints:</p><ul><li><code>POST /api/v1/webhook-receiver</code> — Receives hook payloads from Claude Code. Stores in DB. Returns 200 with empty JSON (no decision, pure logging)</li><li><code>GET /api/v1/webhook-receiver/events</code> — Query stored events with filters (event_type, session_id, time range, limit/offset)</li><li><code>GET /api/v1/webhook-receiver/stats</code> — Aggregated stats: events by type, events per hour/day, most common tools</li><li><code>DELETE /api/v1/webhook-receiver/events</code> — Clear events older than N days (with query param)</li></ul><p>Register in <code>backend/app/api/v1/router.py</code>.</p><h4 id="_2-3-webhook-receiver-service" tabindex="-1">2.3 Webhook Receiver Service <a class="header-anchor" href="#_2-3-webhook-receiver-service" aria-label="Permalink to &quot;2.3 Webhook Receiver Service&quot;">​</a></h4><p><strong>New file: <code>backend/app/services/webhook_receiver_service.py</code></strong></p><ul><li><code>store_event(payload: dict)</code> — Parse and store incoming hook event</li><li><code>get_events(filters)</code> — Query with pagination and filtering</li><li><code>get_stats(time_range)</code> — Aggregate statistics</li><li><code>cleanup_events(older_than_days)</code> — Delete old events</li></ul><h4 id="_2-4-frontend-activity-tab" tabindex="-1">2.4 Frontend: Activity Tab <a class="header-anchor" href="#_2-4-frontend-activity-tab" aria-label="Permalink to &quot;2.4 Frontend: Activity Tab&quot;">​</a></h4><p><strong>New file: <code>frontend/src/features/hooks/HookActivityTab.tsx</code></strong></p><p>Added as a tab within HooksPage.tsx (alongside event-type tabs):</p><ul><li><strong>Stats row</strong>: Cards showing &quot;Events Today&quot;, &quot;Events This Week&quot;, &quot;Most Active Event&quot;, &quot;Unique Sessions&quot;</li><li><strong>Events timeline</strong>: Table/list of recent events with columns: Time, Event Type, Tool, Session ID, expandable payload</li><li><strong>Filters</strong>: Event type dropdown, time range picker, session ID search</li><li><strong>Auto-refresh</strong>: Toggle for polling every 5 seconds</li><li><strong>Clear button</strong>: Delete old events</li></ul><h4 id="_2-5-frontend-connect-to-deck-dialog" tabindex="-1">2.5 Frontend: Connect to Deck Dialog <a class="header-anchor" href="#_2-5-frontend-connect-to-deck-dialog" aria-label="Permalink to &quot;2.5 Frontend: Connect to Deck Dialog&quot;">​</a></h4><p><strong>New file: <code>frontend/src/features/hooks/ConnectToDeckDialog.tsx</code></strong></p><p>Accessible from a &quot;Connect to Deck&quot; button on the Hooks page header:</p><ul><li>Checkbox list of all event types to monitor</li><li>Scope selector (user/project)</li><li>Shows the generated webhook URL (e.g., <code>http://localhost:8000/api/v1/webhook-receiver</code>)</li><li>&quot;Connect&quot; button creates HTTP hooks for all selected events via the existing hooks API</li><li>Success confirmation with link to Activity tab</li></ul><h4 id="_2-6-frontend-api-hook" tabindex="-1">2.6 Frontend API Hook <a class="header-anchor" href="#_2-6-frontend-api-hook" aria-label="Permalink to &quot;2.6 Frontend API Hook&quot;">​</a></h4><p><strong>File: <code>frontend/src/features/hooks/api.ts</code></strong> (or new file)</p><ul><li><code>fetchHookEvents(filters)</code> — GET /api/v1/webhook-receiver/events</li><li><code>fetchHookStats(timeRange)</code> — GET /api/v1/webhook-receiver/stats</li><li><code>clearHookEvents(olderThanDays)</code> — DELETE /api/v1/webhook-receiver/events</li></ul><hr><h2 id="implementation-phases" tabindex="-1">Implementation Phases <a class="header-anchor" href="#implementation-phases" aria-label="Permalink to &quot;Implementation Phases&quot;">​</a></h2><h3 id="phase-1-schema-types-backend-frontend" tabindex="-1">Phase 1: Schema &amp; Types (backend + frontend) <a class="header-anchor" href="#phase-1-schema-types-backend-frontend" aria-label="Permalink to &quot;Phase 1: Schema &amp; Types (backend + frontend)&quot;">​</a></h3><ul><li>Add HTTP fields to Pydantic schemas and TypeScript types</li><li>Add 5 new event types to both backend and frontend</li><li>Fix type validation bug in hooks API route</li></ul><h3 id="phase-2-backend-service-updates" tabindex="-1">Phase 2: Backend Service Updates <a class="header-anchor" href="#phase-2-backend-service-updates" aria-label="Permalink to &quot;Phase 2: Backend Service Updates&quot;">​</a></h3><ul><li>Hook service reads/writes HTTP hook fields (url, headers, allowedEnvVars)</li><li>API route validation for HTTP hooks</li></ul><h3 id="phase-3-frontend-http-hook-ui" tabindex="-1">Phase 3: Frontend HTTP Hook UI <a class="header-anchor" href="#phase-3-frontend-http-hook-ui" aria-label="Permalink to &quot;Phase 3: Frontend HTTP Hook UI&quot;">​</a></h3><ul><li>KeyValueEditor shared component</li><li>HookWizard Step 3 HTTP type + form</li><li>HookEditor HTTP fields</li><li>HookCard and HookDetailDialog HTTP display</li><li>HTTP hook templates</li></ul><h3 id="phase-4-webhook-receiver-backend" tabindex="-1">Phase 4: Webhook Receiver Backend <a class="header-anchor" href="#phase-4-webhook-receiver-backend" aria-label="Permalink to &quot;Phase 4: Webhook Receiver Backend&quot;">​</a></h3><ul><li>HookEvent database model</li><li>Webhook receiver API endpoints</li><li>Webhook receiver service</li></ul><h3 id="phase-5-activity-dashboard-connect-to-deck" tabindex="-1">Phase 5: Activity Dashboard + Connect to Deck <a class="header-anchor" href="#phase-5-activity-dashboard-connect-to-deck" aria-label="Permalink to &quot;Phase 5: Activity Dashboard + Connect to Deck&quot;">​</a></h3><ul><li>HookActivityTab component with stats, timeline, filters</li><li>Integrate as tab in HooksPage</li><li>ConnectToDeckDialog for one-click setup</li><li>API hooks for webhook receiver endpoints</li></ul><hr><h2 id="key-files-to-modify" tabindex="-1">Key Files to Modify <a class="header-anchor" href="#key-files-to-modify" aria-label="Permalink to &quot;Key Files to Modify&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Changes</th></tr></thead><tbody><tr><td><code>backend/app/models/schemas.py</code></td><td>Add url, headers, allowedEnvVars to Hook models; add 5 new events</td></tr><tr><td><code>backend/app/models/database.py</code></td><td>Add HookEvent ORM model</td></tr><tr><td><code>backend/app/api/v1/hooks.py</code></td><td>Fix type validation bug; add HTTP validation</td></tr><tr><td><code>backend/app/api/v1/router.py</code></td><td>Register webhook_receiver routes</td></tr><tr><td><code>backend/app/services/hook_service.py</code></td><td>Read/write HTTP hook fields</td></tr><tr><td><code>frontend/src/types/hooks.ts</code></td><td>Add &quot;http&quot; type, HTTP fields, new events, templates</td></tr><tr><td><code>frontend/src/features/hooks/HooksPage.tsx</code></td><td>Add Activity tab, Connect to Deck button</td></tr><tr><td><code>frontend/src/features/hooks/HookWizard.tsx</code></td><td>HTTP type selection + form</td></tr><tr><td><code>frontend/src/features/hooks/HookEditor.tsx</code></td><td>HTTP type fields</td></tr><tr><td><code>frontend/src/features/hooks/HookCard.tsx</code></td><td>HTTP type display</td></tr><tr><td><code>frontend/src/features/hooks/HookDetailDialog.tsx</code></td><td>HTTP detail section</td></tr></tbody></table><h2 id="new-files-to-create" tabindex="-1">New Files to Create <a class="header-anchor" href="#new-files-to-create" aria-label="Permalink to &quot;New Files to Create&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>frontend/src/components/shared/KeyValueEditor.tsx</code></td><td>Reusable key-value pair editor</td></tr><tr><td><code>backend/app/api/v1/webhook_receiver.py</code></td><td>Webhook receiver API routes</td></tr><tr><td><code>backend/app/services/webhook_receiver_service.py</code></td><td>Webhook receiver business logic</td></tr><tr><td><code>frontend/src/features/hooks/HookActivityTab.tsx</code></td><td>Activity dashboard tab</td></tr><tr><td><code>frontend/src/features/hooks/ConnectToDeckDialog.tsx</code></td><td>One-click setup dialog</td></tr></tbody></table><h2 id="existing-patterns-to-reuse" tabindex="-1">Existing Patterns to Reuse <a class="header-anchor" href="#existing-patterns-to-reuse" aria-label="Permalink to &quot;Existing Patterns to Reuse&quot;">​</a></h2><ul><li><code>CLICKABLE_CARD</code> constant from <code>@/lib/constants</code> for any new card components</li><li><code>MODAL_SIZES</code> from <code>@/lib/constants</code> for dialog sizing</li><li><code>MarkdownRenderer</code> / <code>MarkdownPreviewToggle</code> from <code>@/components/shared/</code> for any markdown content</li><li>Recharts (already a dependency) for activity charts</li><li>Badge, Card, Dialog, Tabs from shadcn/ui (already installed)</li><li><code>useApi</code> hook pattern from <code>frontend/src/hooks/</code> for new API calls</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><ol><li><strong>Unit test</strong>: Run <code>cd backend &amp;&amp; pytest tests/</code> after schema and service changes</li><li><strong>Manual test — HTTP hook CRUD</strong>: Create, edit, view, delete an HTTP hook via the UI. Verify settings.json contains correct <code>type: &quot;http&quot;</code>, <code>url</code>, <code>headers</code>, <code>allowedEnvVars</code></li><li><strong>Manual test — webhook receiver</strong>: Use curl to POST a sample hook payload to <code>/api/v1/webhook-receiver</code> and verify it appears in the Activity tab</li><li><strong>Manual test — Connect to Deck</strong>: Use the dialog to create monitoring hooks, then verify they appear in settings.json and the Activity tab receives events</li><li><strong>Manual test — existing hooks</strong>: Verify command, prompt, and agent hooks still work correctly after changes</li><li><strong>Lint</strong>: Run <code>cd frontend &amp;&amp; npm run lint</code> to ensure no TypeScript errors</li></ol>`,80)])])}const k=o(d,[["render",n]]);export{u as __pageData,k as default};
